<?php
require_once __DIR__.'/../app/bootstrap.php';require_admin();
$q=mb_substr(input_text($_GET,'q'),0,120);$status=input_text($_GET,'status','all');$page=max(1,(int)input_text($_GET,'page','1'));$where=[];$parameters=[];
if($q!==''){$where[]='(s.name LIKE ? OR c.name LIKE ?)';$parameters[]='%'.$q.'%';$parameters[]='%'.$q.'%';}
if(in_array($status,['published','draft'],true)){$where[]='s.is_active=?';$parameters[]=$status==='published'?1:0;}
$condition=$where?' WHERE '.implode(' AND ',$where):'';
$total=(int)query('SELECT COUNT(*) FROM services s JOIN categories c ON c.id=s.category_id'.$condition,$parameters)->fetchColumn();$pages=max(1,(int)ceil($total/10));$page=min($page,$pages);$offset=($page-1)*10;
$items=query('SELECT s.*,c.name AS category FROM services s JOIN categories c ON c.id=s.category_id'.$condition.' ORDER BY s.id DESC LIMIT 10 OFFSET '.$offset,$parameters)->fetchAll();
$pageTitle='Medical services | Wellnest Workspace';$adminSection='services';$adminPageLabel='Medical services';require __DIR__.'/../components/admin_header.php';
?>
<div class="admin-page-heading"><div><span class="admin-eyebrow">THOUGHTFUL CARE, CLEARLY PRESENTED</span><h1>Medical services<span>.</span></h1><p>Create, refine, and organize the care your clinic offers.</p></div><a class="btn btn-primary" href="<?=e(base_url('admin/service_form.php'))?>"><?=icon('plus')?> Add service</a></div>
<section class="admin-panel"><div class="services-toolbar"><form method="get" class="admin-filter-form"><div class="admin-search"><?=icon('search')?><label class="visually-hidden" for="admin-search">Search services or categories</label><input type="search" name="q" id="admin-search" value="<?=e($q)?>" placeholder="Search services or categories…"></div><label class="visually-hidden" for="status-filter">Publication status</label><select class="form-select" id="status-filter" name="status"><?php foreach(['all'=>'All statuses','published'=>'Published','draft'=>'Draft'] as $key=>$label): ?><option value="<?=$key?>" <?=$status===$key?'selected':''?>><?=$label?></option><?php endforeach; ?></select><button class="btn btn-outline-primary" type="submit">Apply filters</button><?php if($q!==''||$status!=='all'): ?><a class="clear-filters" href="<?=e(base_url('admin/services.php'))?>">Clear</a><?php endif; ?></form><span class="results-label"><?=$total?> <?=$total===1?'service':'services'?></span></div><div class="admin-table-wrap"><table class="admin-table services-table"><thead><tr><th>Service</th><th>Category</th><th>Consultation fee</th><th>Status</th><th class="text-end">Actions</th></tr></thead><tbody><?php foreach($items as $item): ?><tr><td><div class="table-service"><img src="<?=e(base_url('public/images/'.$item['image']))?>" alt="<?=e($item['alt'])?>" width="52" height="52"><div><strong><?=e($item['name'])?></strong><small><?=e($item['duration'])?> min consultation · #<?=e($item['id'])?></small></div></div></td><td data-label="Category"><span class="category-tag"><?=e($item['category'])?></span></td><td data-label="Fee"><strong><?=money((int)$item['price'])?></strong><small>VND / consultation</small></td><td data-label="Status"><span class="status-badge <?=$item['is_active']?'status-published':'status-draft'?>"><?=$item['is_active']?'Published':'Draft'?></span></td><td><div class="table-actions"><a href="<?=e(base_url('admin/service_form.php?id='.$item['id']))?>" class="table-action" aria-label="Edit <?=e($item['name'])?>" title="Edit service"><?=icon('edit')?></a><?php if($item['is_active']): ?><a href="<?=e(base_url('pages/item_details.php?id='.$item['id']))?>" class="table-action" aria-label="View <?=e($item['name'])?>" title="View public page"><?=icon('arrow-up')?></a><?php endif; ?><a href="<?=e(base_url('admin/service_delete.php?id='.$item['id']))?>" class="table-action danger" aria-label="Delete <?=e($item['name'])?>" title="Delete service"><?=icon('trash')?></a></div></td></tr><?php endforeach; ?><?php if(!$items): ?><tr><td colspan="5" class="table-empty"><?=icon('search')?><h2>No services found.</h2><p>Try another search or add your first medical service.</p><a href="<?=e(base_url('admin/service_form.php'))?>" class="btn btn-primary">Add service</a></td></tr><?php endif; ?></tbody></table></div><div class="table-pagination"><span><?=$total?'Showing '.($offset+1).'–'.min($offset+10,$total).' of '.$total.' services':'No results'?></span><nav aria-label="Service list pages"><?php for($number=1;$number<=$pages;$number++): ?><a class="<?=$number===$page?'active':''?>" <?=$number===$page?'aria-current="page"':''?> href="<?=e(base_url('admin/services.php?'.http_build_query(['q'=>$q,'status'=>$status,'page'=>$number])))?>"><?=$number?></a><?php endfor; ?></nav></div></section><p class="admin-bottom-note"><?=icon('shield')?> Published services appear immediately on the public website. Drafts stay in your workspace.</p>
